"""Профильные семейства v2: фиксированная рубрика, случайные параметры.

Возвращают проверяемые численные ответы. Это узкая проверка инженерных основ,
а не замена практическому интервью; экспертная калибровка описана в model card.
"""
import math


def track_questions(spec, level, rng):
    a, b, c = rng.randint(4, 12), rng.randint(2, 5), rng.randint(2, 4)
    # Каждый уровень имеет свой чертёж, одинаковый для всех вариантов уровня.
    if spec == "fullstack":
        return [
            ("API", f"API отдаёт {a*b+1} записей страницами по {a}. Сколько запросов нужно для получения всех записей?", b+1, "Округление количества записей / размера страницы вверх."),
            ("Транзакции", f"Есть {a} заказов. Для каждого выполняется одна транзакция и {level+1} запросов внутри неё. Сколько запросов выполнится без повторов?", a*(level+1), "Число заказов умножаем на число запросов."),
            ("Кэш", f"В {a*b} чтениях доля попаданий в кэш равна {b-1}/{b}. Каждый промах выполняет {level} SQL-запроса. Сколько SQL-запросов выполнено?", a*level, "Промахов a; каждый выполняет заданное число запросов."),
            ("Идемпотентность", f"{a} различных платежей отправлены по {b+level} раз. Сервер атомарно сохраняет idempotency key и результат. Сколько успешных списаний допустимо?", a, "Один эффект на уникальный ключ."),
        ]
    if spec == "mobile":
        return [
            ("Графика", f"Изображение {a*10} × {b*10} пикселей хранится без сжатия, {level+1} байта на пиксель. Сколько байт занимает буфер?", a*b*100*(level+1), "Ширина × высота × байты на пиксель."),
            ("Сеть", f"Клиент скачивает {a*b} КБ со скоростью {a} КБ/с. Перед передачей выполняется {level} последовательных запросов по {c} секунд каждый. Сколько секунд займёт всё действие?", b+level*c, "Время запросов плюс размер / скорость."),
            ("Синхронизация", f"В офлайн-очереди {a*b} операций: {a} уникальных ID по {b} копии каждого. После дедупликации каждую операцию разбивают на {level} независимых запросов. Сколько запросов отправят?", a*level, "Сначала оставляем уникальные операции, затем раскрываем их запросы."),
            ("Жизненный цикл", f"Экран подписался на {a} событий, при уходе отменил {a-c} подписок. После {level} одинаковых посещений сколько подписок осталось, если ID подписок всегда новые?", c*level, "На каждом посещении остаются c подписок."),
        ]
    if spec == "qa":
        return [
            ("Тест-дизайн", f"Форма имеет {a} допустимых типов, {b} состояний и {level+1} ролей. Сколько тестов в полном декартовом произведении?", a*b*(level+1), "Перемножаем мощности независимых наборов."),
            ("Граничные значения", f"Целое число допустимо от {a} до {a+b*level} включительно. Сколько допустимых значений?", b*level+1, "Включённые границы: верхняя − нижняя + 1."),
            ("Автоматизация", f"{a*b*level} независимых тестов распределены поровну на {b} исполнителей. Каждый тест занимает {c} секунд. Накладных расходов нет. Сколько секунд занимает прогон?", a*level*c, "Число тестов на исполнителя умножаем на время теста."),
            ("Диагностика", f"Первый прогон дал {a+b} падений, повторный — {b+c}. Пересечение — {b}. Сколько уникальных тестов падало хотя бы раз?", a+b+c, "Мощность объединения: A + B − пересечение."),
        ]
    if spec == "devops":
        return [
            ("Масштабирование", f"Нужно обработать {a*b*level+1} запросов/с. Одна реплика выдерживает {a} запросов/с. Каково минимальное число реплик?", b*level+1, "Округляем нагрузку / ёмкость реплики вверх."),
            ("Ресурсы", f"В кластере {a} узлов по {b*level} ГБ доступной памяти. Под запрашивает {level} ГБ. Без других ограничений сколько подов поместится?", a*b, "Суммарная доступная память / запрос одного пода."),
            ("Надёжность", f"Сервис имеет {a+b} реплик. Rolling update разрешает maxUnavailable={b}. Дополнительно отказало {level} доступных реплик. Сколько реплик осталось доступными?", a-level, "Вычитаем планово недоступные и дополнительные отказы."),
            ("Восстановление", f"Последняя полная копия требует {a*b} минут восстановления. После неё нужно последовательно применить {level+c} журналов по {b} минут. Каково расчётное время восстановления в минутах?", a*b+(level+c)*b, "Полная копия плюс последовательное применение журналов."),
        ]
    if spec == "data_engineering":
        return [
            ("SQL", f"Таблица содержит {a} ключей по {b*level} строк каждый. После GROUP BY key без HAVING сколько строк вернёт запрос?", a, "Одна строка на уникальную группу."),
            ("Потоки", f"Получено {a*b*level} событий, по {b} копии каждого event_id. После дедупликации каждое уникальное событие порождает {c} строки. Сколько строк будет записано?", a*level*c, "Дедупликация до раскрытия события в строки."),
            ("Партиционирование", f"Есть {a*b*level} равномерно распределённых строк в {a} партициях. Запрос читает {c} партиции. Сколько строк он просмотрит?", b*level*c, "Строк на партицию × число выбранных партиций."),
            ("Пайплайны", f"Этап A занимает {a} минут. После A этапы B ({b*level} минут) и C ({c*level} минут) идут параллельно. После обоих — D ({b} минут). Сколько минут занимает критический путь?", a+max(b*level,c*level)+b, "A + максимум параллельных ветвей + D."),
        ]
    if spec == "data_science":
        return [
            ("Статистика", f"Выборка состоит из чисел {a*level}, {a*level+b}, {a*level+2*b}. Каково среднее арифметическое?", a*level+b, "Среднее равно сумме, делённой на три."),
            ("Метрики ML", f"Классификатор нашёл {a*b} истинно положительных и {a*(10-b)} ложноположительных объектов. Чему равна precision в процентах?", b*10, "TP / (TP + FP) × 100."),
            ("Валидация", f"В датасете {a*b*100} наблюдений. {b*10}% отложено в test. Из оставшегося train {c*10}% отложено в validation. Сколько наблюдений осталось для обучения?", a*b*(10-b)*(10-c), "Доли применяются последовательно, без использования test в обучении."),
            ("Признаки", f"Числовых признаков {a*level}. Категория с {b} значениями кодируется one-hot с drop-first. Сколько всего столбцов поступит в модель?", a*level+b-1, "Числовые признаки + k − 1 индикатор."),
        ]
    if spec == "cybersecurity":
        return [
            ("Контроль доступа", f"Есть {a} пользователей, каждый имеет {b} различных персональных разрешений. {level} пользователей заблокированы, их разрешения отозваны. Сколько разрешений осталось?", (a-level)*b, "Учитываем только активных пользователей."),
            ("Сессии", f"Токен создан в минуту {a}, живёт {b*level} минут; он недействителен при t >= issued+TTL. В какую минуту он впервые станет недействительным?", a+b*level, "Момент выпуска плюс TTL."),
            ("Аудит", f"В SIEM поступило {a*b*level} записей. Каждое уникальное событие повторилось ровно {b} раз. Сколько уникальных событий нужно расследовать?", a*level, "Общее число делим на кратность копирования."),
            ("Ограничения доступа", f"За окно лимита пришло {a*b} попыток входа с одного IP. Разрешено не более {a+level}. Сколько попыток будет отклонено?", a*b-a-level, "Все попытки сверх разрешённого лимита отклоняются."),
        ]
    if spec == "systems_analysis":
        return [
            ("Моделирование", f"Есть {a} состояний. Из каждого разрешены переходы в любые другие состояния без перехода в себя. Сколько ориентированных переходов в модели?", a*(a-1), "Из каждого состояния есть n−1 исходящих переходов."),
            ("Требования", f"Требований {a*b*level}. Для {a*level} требований нет приёмочных сценариев. Сколько требований покрыто сценариями?", a*level*(b-1), "Общее количество минус непокрытые требования."),
            ("Контракты API", f"Пагинация возвращает {a} элементов на страницу. Всего элементов {a*b+level}. Сколько страниц нужно?", math.ceil((a*b+level)/a), "Деление с округлением вверх, включая неполную страницу."),
            ("Процессы", f"После этапа A ({a} минут) выполняются параллельно B ({b*level} минут) и C ({c*level} минут), затем D ({b} минут). Какова минимальная длительность процесса?", a+max(b*level,c*level)+b, "Последовательные этапы суммируются, параллельные берутся по максимуму."),
        ]
    raise ValueError(f"Нет чертежа для специализации {spec}")
